/* @autogenerated */
import { signal } from '@angular/core';
import { AbstactContainerWrapper } from './abstract-container-wrapper';

class Wrapper extends AbstactContainerWrapper {}

describe('AbstactContainerWrapper', () => {
  const container = () =>
    ({
      theToolbarTemplate: signal('toolbar'),
      theContextTemplate: signal('context'),
      theSelectionTemplate: signal('selection'),
      selectionModel: { selected: signal([]) },
      hasSelection: () => true,
      hasMultiple: () => false,
      defaultAction: jasmine.createSpy('defaultAction'),
      executeAction: jasmine.createSpy('executeAction'),
      close: jasmine.createSpy('close'),
    }) as any;

  it('delegates on the action container it wraps', () => {
    const wrapped = container();
    const wrapper = new Wrapper();
    wrapper.actions = signal(wrapped);

    expect(wrapper.theToolbarTemplate()).toBe('toolbar' as any);
    expect(wrapper.theContextTemplate()).toBe('context' as any);
    expect(wrapper.theSelectionTemplate()).toBe('selection' as any);
    expect(wrapper.selectionModel).toBe(wrapped.selectionModel);
    expect(wrapper.hasSelection()).toBeTrue();
    expect(wrapper.hasMultiple()).toBeFalse();

    wrapper.defaultAction([1]);
    wrapper.execute('edit', [1]);
    wrapper.close();

    expect(wrapped.defaultAction).toHaveBeenCalledWith([1]);
    expect(wrapped.executeAction).toHaveBeenCalledWith('edit', [1]);
    expect(wrapped.close).toHaveBeenCalled();
  });

  it('has no selection before the container exists', () => {
    const wrapper = new Wrapper();
    wrapper.actions = signal(undefined);

    expect(wrapper.hasSelection()).toBeFalse();
    expect(wrapper.hasMultiple()).toBeFalse();
    expect(() => wrapper.close()).not.toThrow();
  });
});
